 arc("Rising Ape", P1, [[[ENV], [T("Opening", 2)]], [[T("Tireless")], [T("Hope", 2)]], [[T("Hope")], [ENV]], [[RED, T("Break")]], [[T("Reposition")], [PR]], [[T("Hope"), T("Opening")]], [[T("Closing"), T("AISuppress")]], [[T("PowerDicePromotion")]]], [DAG]),
