 tech("Cold Open", "Investigation 1-2", [H(1)], "If the Knight Pool is empty, place an Opening [Opening] and a Break [Break] token in the Knight Pool.", "cooldown", [O("coldOpen")], "free", OPc, [("HUMAN", "Additionally, gain Provoke.")], form={"HUMAN": ADD(O("provoke"))}),
