 tech("Exploit Flaw", "Investigation 2-2", [H(2)], "When you are about to attack, gain Deadly.", "cooldown", [O("exploitFlaw")], "beforeAttack", OPc, [("HUMAN", "You may gain Precise instead.")], form={"HUMAN": INS(O("exploitFlaw", precise=True))}),
 tech("Primal Leap", "Investigation 2-3", [H(1)], "Jump.", "cooldown", [O("jump")], "free", PRc, [("DEVIL", "Advanced Jump."), ("APE", "Additionally, gain +1 Speed [Speed] until the end of your turn.")], form={"APE": ADD(O("turnSpeed", n=1))}, unclear=["Jump / Advanced Jump are not implemented (only the APE Speed bonus)"]),
 tech("Force of Nature", "Quest: Primal Warrior", [H(2)], "Use this Technique when you are about to attack. Ignore Wound Responses during this Attack.", "discard", [O("ignoreResponses")], "beforeAttack", ex("Break", "discard"), [("HUMAN", "Additionally, gain \"Overpower 3+: Rouse 1.\"")], form={"HUMAN": ADD(O("overRouse", need=3, n=1))}, unclear=["All Responses of the Attack are ignored (the engine does not separate Wound Responses)"]),
