 tech("Fist of the Firstmen", "Investigation 4-3", [H(2)], "During the first ability window, gain Auto-hope 1 and +1 [Power].", "discard", [O("fistFirstmen")], "beforeAttack", ex("PowerReroll", "discard"), [("APE", "Additionally gain Daze and +1 [Power].")], form={"APE": INS(O("fistFirstmen", ape=True))}),
